import 'normalize.css';
import 'uno.css';
import '@/shared/styles/index.scss';
import { updateWasmToMatches } from '@gkd-kit/selector';
import { toMatches } from 'regex-wasm';
import App from './App.vue';
import commitLog from './commit.data';
import router from './router';
import root from '@/shared/lib/root';
import { reportGlobalError } from '@/shared/services/globalError';
import { setSnapshot } from '@/entities/snapshot/storage';

updateWasmToMatches(toMatches);

const app = createApp(App);
app.config.errorHandler = (error, _instance, info) => {
  reportGlobalError(error, `Vue: ${info}`);
};
app.use(router);
app.mount(root);

// 原生 App 注入：检查 window.__GKD_SNAPSHOT__
const initNativeSnapshot = async () => {
  const w = window as unknown as Record<string, unknown>;
  if (w.__GKD_SNAPSHOT__) {
    try {
      const snapshot = typeof w.__GKD_SNAPSHOT__ === 'string'
        ? JSON.parse(w.__GKD_SNAPSHOT__ as string)
        : w.__GKD_SNAPSHOT__;
      let bf = new ArrayBuffer(0);
      if (w.__GKD_SCREENSHOT__) {
        const binary = atob(w.__GKD_SCREENSHOT__ as string);
        const bytes = new Uint8Array(binary.length);
        for (let i = 0; i < binary.length; i++) {
          bytes[i] = binary.charCodeAt(i);
        }
        bf = bytes.buffer;
      }
      await setSnapshot(snapshot as never, bf);
      console.log('[GKD] 原生快照已加载');
    } catch (e) {
      console.error('[GKD] 原生快照加载失败', e);
    }
  }
};
setTimeout(initNativeSnapshot, 800);

if (import.meta.env.PROD) {
  console.log(commitLog);
}
